files.content:
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
}

body {
  background: #1c1c1e;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  font-family: -apple-system, 'SF Pro Display', 'Helvetica Neue', sans-serif;
}

.calculator {
  width: 390px;
  background: #000;
  border-radius: 54px;
  overflow: hidden;
  box-shadow: 0 40px 100px rgba(0,0,0,0.8), 0 0 0 1px rgba(255,255,255,0.08);
  padding-bottom: 28px;
}

.display {
  padding: 24px 24px 12px 24px;
  min-height: 210px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: flex-end;
  gap: 4px;
}

.expression {
  font-size: 22px;
  color: rgba(255,255,255,0.45);
  font-weight: 300;
  letter-spacing: 0.3px;
  min-height: 28px;
  word-break: break-all;
  text-align: right;
}

.result {
  font-size: 88px;
  font-weight: 200;
  color: #fff;
  line-height: 1;
  letter-spacing: -3px;
  transition: font-size 0.1s ease;
  text-align: right;
  word-break: break-all;
}

.result.small { font-size: 60px; letter-spacing: -2px; }
.result.xsmall { font-size: 42px; letter-spacing: -1px; }

.buttons {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  padding: 12px 16px 0 16px;
}

.btn {
  width: 100%;
  aspect-ratio: 1;
  border: none;
  border-radius: 50%;
  font-size: 32px;
  font-weight: 400;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: filter 0.08s ease, transform 0.06s ease;
  outline: none;
  -webkit-font-smoothing: antialiased;
  font-family: -apple-system, 'SF Pro Display', 'Helvetica Neue', sans-serif;
  position: relative;
  overflow: hidden;
}

.btn svg {
  width: 28px;
  height: 28px;
}

.btn:active {
  filter: brightness(1.35);
  transform: scale(0.94);
}

.btn.dark {
  background: #333335;
  color: #fff;
}

.btn.gray {
  background: #636366;
  color: #fff;
}

.btn.orange {
  background: #ff9f0a;
  color: #fff;
}

.btn.orange.active {
  background: #fff;
  color: #ff9f0a;
}

.btn.special {
  font-size: 22px;
}

@media (max-width: 420px) {
  .calculator {
    width: 100vw;
    border-radius: 0;
    min-height: 100vh;
    padding-bottom: env(safe-area-inset-bottom, 20px);
  }
  .display {
    min-height: 30vh;
  }
  .buttons {
    gap: 10px;
    padding: 10px 12px 0 12px;
  }
}

const resultEl = document.getElementById('result');
const expressionEl = document.getElementById('expression');

let currentValue = '0';
let previousValue = '';
let operator = null;
let waitingForOperand = false;
let justEvaluated = false;
let lastOperator = null;
let lastOperand = null;

function formatNumber(num) {
  const n = parseFloat(num);
  if (isNaN(n)) return 'Error';
  if (!isFinite(n)) return n > 0 ? '∞' : '-∞';

  let str = '';
  if (Math.abs(n) >= 1e15) {
    str = n.toExponential(6).replace('e+', 'e');
  } else {
    const parts = num.toString().split('.');
    const intPart = parts[0];
    const decPart = parts[1];
    if (intPart.replace('-','').length > 9 && !decPart) {
      str = n.toPrecision(9).replace(/\.?0+$/, '');
    } else {
      str = num;
    }
  }

  return str;
}

function displayFormat(val) {
  const n = parseFloat(val);
  if (isNaN(n)) return val;
  if (!isFinite(n)) return n > 0 ? '∞' : '-∞';

  const s = val.toString();
  const hasDot = s.includes('.');

  if (hasDot) {
    const [int, dec] = s.split('.');
    const formattedInt = parseInt(int).toLocaleString('en-US');
    return dec !== undefined ? formattedInt + '.' + dec : formattedInt;
  }
  return parseInt(s).toLocaleString('en-US');
}

function updateDisplay() {
  const display = displayFormat(currentValue);
  resultEl.textContent = display;
  const len = display.replace(/[,.-]/g, '').length;
  resultEl.className = 'result';
  if (len > 9) resultEl.classList.add('small');
  if (len > 13) resultEl.classList.add('xsmall');
}

function inputNumber(val) {
  if (waitingForOperand) {
    currentValue = val;
    waitingForOperand = false;
  } else {
    if (justEvaluated) {
      currentValue = val;
      justEvaluated = false;
      expressionEl.textContent = '';
    } else {
      if (currentValue === '0') {
        currentValue = val;
      } else {
        if (currentValue.replace('-', '').replace('.', '').length >= 9) return;
        currentValue += val;
      }
    }
  }
  updateDisplay();
}

function inputDecimal() {
  if (waitingForOperand) {
    currentValue = '0.';
    waitingForOperand = false;
    updateDisplay();
    return;
  }
  if (!currentValue.includes('.')) {
    currentValue += '.';
    updateDisplay();
  }
}

function inputOperator(op) {
  document.querySelectorAll('.btn.orange').forEach(b => b.classList.remove('active'));
  const btn = [...document.querySelectorAll('.btn.orange')].find(b => b.dataset.value === op || (op === '÷' && b.dataset.value === '÷') || (op === '×' && b.dataset.value === '×') || (op === '−' && b.dataset.value === '−') || (op === '+' && b.dataset.value === '+'));
  if (btn) btn.classList.add('active');

  const current = parseFloat(currentValue);

  if (operator && !waitingForOperand) {
    const prev = parseFloat(previousValue);
    const result = calculate(prev, current, operator);
    currentValue = String(result);
    expressionEl.textContent = displayFormat(String(result)) + ' ' + op;
    previousValue = String(result);
  } else {
    expressionEl.textContent = displayFormat(currentValue) + ' ' + op;
    previousValue = currentValue;
  }

  operator = op;
  waitingForOperand = true;
  justEvaluated = false;
  updateDisplay();
}

function calculate(a, b, op) {
  switch(op) {
    case '+': return a + b;
    case '−': return a - b;
    case '×': return a * b;
    case '÷': return b === 0 ? NaN : a / b;
    default: return b;
  }
}

function equals() {
  document.querySelectorAll('.btn.orange').forEach(b => b.classList.remove('active'));

  if (!operator && !justEvaluated) return;

  const current = parseFloat(currentValue);
  let operand = waitingForOperand ? parseFloat(previousValue) : current;
  let op = operator;

  if (justEvaluated) {
    operand = lastOperand;
    op = lastOperator;
  }

  const prev = justEvaluated ? parseFloat(currentValue) : parseFloat(previousValue);

  if (!justEvaluated) {
    lastOperand = current;
    lastOperator = operator;
  }

  const result = calculate(prev, operand, op);
  const resultStr = Number.isInteger(result) ? String(result) : String(parseFloat(result.toPrecision(12)));

  if (!justEvaluated) {
    expressionEl.textContent = displayFormat(previousValue) + ' ' + op + ' ' + displayFormat(String(operand)) + ' =';
  } else {
    expressionEl.textContent = displayFormat(currentValue) + ' ' + op + ' ' + displayFormat(String(operand)) + ' =';
  }

  currentValue = resultStr;
  operator = null;
  waitingForOperand = false;
  justEvaluated = true;
  updateDisplay();
}

function clearAll() {
  currentValue = '0';
  previousValue = '';
  operator = null;
  waitingForOperand = false;
  justEvaluated = false;
  lastOperand = null;
  lastOperator = null;
  expressionEl.textContent = '';
  document.querySelectorAll('.btn.orange').forEach(b => b.classList.remove('active'));
  updateDisplay();
}

function backspace() {
  if (justEvaluated || waitingForOperand) return;
  if (currentValue.length <= 1 || (currentValue.length === 2 && currentValue.startsWith('-'))) {
    currentValue = '0';
  } else {
    currentValue = currentValue.slice(0, -1);
  }
  updateDisplay();
}

function percent() {
  const n = parseFloat(currentValue);
  if (operator && previousValue !== '') {
    currentValue = String((parseFloat(previousValue) * n) / 100);
  } else {
    currentValue = String(n / 100);
  }
  updateDisplay();
}

function negate() {
  if (currentValue === '0') return;
  currentValue = currentValue.startsWith('-') ? currentValue.slice(1) : '-' + currentValue;
  updateDisplay();
}

// Event listeners
document.querySelectorAll('.btn').forEach(btn => {
  btn.addEventListener('click', () => {
    const action = btn.dataset.action;
    const value = btn.dataset.value;

    if (action === 'number') inputNumber(value);
    else if (action === 'operator') inputOperator(value);
    else if (action === 'equals') equals();
    else if (action === 'clear') clearAll();
    else if (action === 'decimal') inputDecimal();
    else if (action === 'percent') percent();
    else if (action === 'negate') negate();
    else if (btn.id === 'backspace') backspace();
  });
});

// Keyboard support
document.addEventListener('keydown', e => {
  if (e.key >= '0' && e.key <= '9') inputNumber(e.key);
  else if (e.key === '+') inputOperator('+');
  else if (e.key === '-') inputOperator('−');
  else if (e.key === '*') inputOperator('×');
  else if (e.key === '/') { e.preventDefault(); inputOperator('÷'); }
  else if (e.key === 'Enter' || e.key === '=') equals();
  else if (e.key === 'Backspace') backspace();
  else if (e.key === 'Escape') clearAll();
  else if (e.key === '.') inputDecimal();
  else if (e.key === '%') percent();
});
